## Objective
Implement cross-platform clipboard support for the context command.

## Implementation Steps

### 1. Create clipboard utility
Create `src/lib/clipboard.ts`:

```typescript
import { exec } from "node:child_process";
import { promisify } from "node:util";

const execAsync = promisify(exec);

interface ClipboardResult {
  success: boolean;
  error?: string;
}

export async function copyToClipboard(text: string): Promise<ClipboardResult> {
  const platform = process.platform;

  try {
    if (platform === "darwin") {
      // macOS: use pbcopy
      await execAsync("pbcopy", { input: text });
    } else if (platform === "win32") {
      // Windows: use clip.exe
      await execAsync("clip", { input: text });
    } else {
      // Linux: try xclip, then xsel, then wl-copy (Wayland)
      try {
        await execAsync("xclip -selection clipboard", { input: text });
      } catch {
        try {
          await execAsync("xsel --clipboard --input", { input: text });
        } catch {
          await execAsync("wl-copy", { input: text });
        }
      }
    }
    return { success: true };
  } catch (error) {
    return { 
      success: false, 
      error: `Clipboard not available: ${error.message}` 
    };
  }
}

export function isClipboardAvailable(): boolean {
  // Quick check if any clipboard tool exists
  // Implementation varies by platform
}
```

### 2. Integrate with context command
In `src/commands/context.ts`:
```typescript
if (options.clipboard) {
  const result = await copyToClipboard(formatted.content);
  if (result.success) {
    console.log(`Copied to clipboard (~${formatted.tokenEstimate} tokens)`);
  } else {
    console.warn(result.error);
    console.log(formatted.content); // Fallback to stdout
  }
} else {
  console.log(formatted.content);
}
```

### 3. Handle large content
- For content >1MB, show warning about potential clipboard issues
- Some systems have clipboard size limits

## Acceptance Criteria
- [ ] `mgrep context -c "query"` copies to clipboard on macOS
- [ ] Works on Windows with clip.exe
- [ ] Works on Linux with xclip, xsel, or wl-copy
- [ ] Falls back to stdout if clipboard unavailable
- [ ] Shows clear error message on failure
- [ ] Warns if content is very large (>1MB)

## Testing Notes
- Test on all 3 platforms (can use CI matrix)
- Test fallback behavior when no clipboard tool installed
- Test with large content (1MB+)

