## Objective
Expose the context export functionality as an MCP tool so AI agents can retrieve formatted context.

## Implementation Steps

### 1. Define tool schema
In `src/commands/watch_mcp.ts`, add new tool registration:

```typescript
{
  name: "mgrep-context",
  description: "Export semantic search results as LLM-optimized context block",
  inputSchema: {
    type: "object",
    properties: {
      query: {
        type: "string",
        description: "Semantic search query"
      },
      format: {
        type: "string",
        enum: ["xml", "markdown", "plain"],
        default: "xml",
        description: "Output format for context"
      },
      max_tokens: {
        type: "number",
        description: "Maximum tokens in output (optional)"
      },
      max_results: {
        type: "number",
        default: 10,
        description: "Maximum number of results to include"
      },
      path: {
        type: "string",
        description: "Filter to specific path prefix"
      }
    },
    required: ["query"]
  }
}
```

### 2. Implement tool handler
```typescript
case "mgrep-context": {
  const { query, format = "xml", max_tokens, max_results = 10, path } = args;

  // Execute search
  const searchResults = await store.search(storeId, query, {
    limit: max_results,
    path: path
  });

  // Format context
  const formatter = new ContextFormatter({
    format,
    maxTokens: max_tokens
  });
  const formatted = formatter.format(searchResults.data);

  return {
    content: [{
      type: "text",
      text: formatted.content
    }],
    metadata: {
      files: formatted.fileCount,
      tokens: formatted.tokenEstimate,
      truncated: formatted.truncated
    }
  };
}
```

### 3. Add tool annotations
```typescript
annotations: {
  readOnlyHint: true  // This tool only reads, no side effects
}
```

